// A review's generated files and snapshots, read apart from its code. A
// tool wrote them, or a test recorded them; the reviewer asks only whether
// they should have changed, not whether each line is right. So each is one
// line — what made it, how much moved — with its lines a click away. Told
// by its name, or by what its first lines say of it. Pure.

/** Names that say a tool made the file, and what to call the tool. */
const BY_NAME: ReadonlyArray<readonly [RegExp, string]> = [
  [/(^|\/)__snapshots__\//, "a test snapshot"],
  [/\.snap$/, "a test snapshot"],
  [/\.ambr$/, "a test snapshot"],
  [/(^|\/)routeTree\.gen\.ts$/, "TanStack Router"],
  [/(^|\/)__generated__\//, "a code generator"],
  [/\.(generated|gen)\.[^/]+$/, "a code generator"],
  [/\.pb\.go$|_pb2(_grpc)?\.pyi?$|_pb\.(js|ts|d\.ts)$|\.pb\.(h|cc|swift)$/, "protoc"],
  [/\.min\.(js|css)$/, "a minifier"],
];

/** What a file's first lines say when a tool wrote it: the marker, and the tool if it names one. */
const MARKERS: ReadonlyArray<RegExp> = [/Code generated by ([^\s.]+).*DO NOT EDIT/i, /@generated(?: by ([^\s*]+))?/, /DO NOT EDIT/, /auto-?generated(?: by ([^\s.,]+))?/i, /This file (?:was|is) (?:automatically )?generated(?: by ([^\s.,]+))?/i];

/** How many first lines a marker is looked for in. */
const HEAD = 10;

/** What made a file, when a tool did: by its name, else by its first lines; null for code a person wrote. */
export const generatedBy = (file: string, text: ReadonlyArray<string> | null): string | null => {
  for (const [name, by] of BY_NAME) if (name.test(file)) return by;
  if (!text) return null;
  // only what its comments say: code that merely mentions a marker is still code
  const head = text
    .slice(0, HEAD)
    .filter((line) => /^\s*(\/\/|#|\/\*|\*|<!--|--|;)/.test(line))
    .join("\n");
  for (const marker of MARKERS) {
    const found = marker.exec(head);
    if (found) return found[1] ? found[1].replace(/[`'"]/g, "") : "a code generator";
  }
  return null;
};
